113	    /** The sheet's dated settings as they stood at the end of a date: every value recorded while the
114	     *  sheet's today was on or before it counts, every later one does not. */
115	    @Transactional(readOnly = true)
116	    public DatedSettings datedAsOf(String sheetId, LocalDate asOf) {
117	        Map<String, Map<LocalDate, String>> byKey = new TreeMap<>();
118	        for (SettingChange change : changes.findBySheetIdOrderByIdAsc(sheetId)) {
119	            if (change.madeBy(asOf)) {
120	                byKey.computeIfAbsent(change.getKey(), k -> new TreeMap<>()).put(change.getFrom(), change.getValue());
121	            }
122	        }
123	        List<SheetSettingDated> then = new ArrayList<>();
124	        byKey.forEach((key, values) -> values.forEach((from, value) ->
125	                then.add(new SheetSettingDated(sheetId, key, from, value))));
126	        return DatedSettings.of(then);
127	    }
