195	    /** Record a dated setting's value (blank: cleared) from a date, or from the sheet's today when none is
196	     *  given; a value already recorded from that date is replaced. The audit line carries the from-date
197	     *  when one was given. */
198	    private void record(String sheetId, String user, String key, String value, LocalDate from) {
199	        sheets.load(sheetId);
200	        LocalDate on = from != null ? from : sheets.today(sheetId);
201	        SheetSettingDated setting = dated.findBySheetIdAndKeyAndFrom(sheetId, key, on).orElse(null);
202	        try {
203	            if (setting == null) {
204	                dated.saveAndFlush(new SheetSettingDated(sheetId, key, on, value));
205	            } else {
206	                setting.setValue(value);
207	                dated.saveAndFlush(setting);
208	            }
209	        } catch (DataIntegrityViolationException raced) {
210	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The setting was changed by someone else.");
211	        }
212	        changes.saveAndFlush(new SettingChange(sheetId, key, on, value, sheets.today(sheetId)));
213	        audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + user + " key=" + key
214	                + " value=" + value + (from == null ? "" : " from=" + from));
215	    }
