404	    /** Refuse an action the user's role is not allowed by the sheet's permission matrix (a blank
405	     *  permission keeps the standing rule), with the action's usual error. */
406	    @Transactional(readOnly = true)
407	    public void refuseUnlessPermitted(String sheetId, String user, String action, String refusal) {
408	        String value = settings.findBySheetIdAndKey(sheetId, permissionKey(action)).map(SheetSetting::getValue)
409	                .orElse("");
410	        Set<Role> allowed = value.isBlank() ? STANDING_PERMISSIONS.get(action) : rolesOf(value);
411	        if (!allowed.contains(roleOf(sheetId, user))) {
412	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, refusal);
413	        }
414	    }
