416	    /** The roles a comma separated list names; refused when one of them is not a role. */
417	    private static Set<Role> rolesOf(String value) {
418	        Set<Role> roles = EnumSet.noneOf(Role.class);
419	        for (String label : value.split(",")) {
420	            roles.add(Role.of(label.trim()).orElseThrow(() -> new ResponseStatusException(HttpStatus.BAD_REQUEST,
421	                    "Name the roles as a comma separated list of clerk and steward.")));
422	        }
423	        return roles;
424	    }
