426	    /** Set the roles that may take an action, as a comma separated list; blank clears it, keeping the
427	     *  standing rule. Not dated. */
428	    @Transactional
429	    public String setPermission(String sheetId, String user, String action, String roles) {
430	        if (!PERMISSION_ACTIONS.contains(action)) {
431	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "No such action.");
432	        }
433	        String value = roles == null || roles.isBlank() ? ""
434	                : String.join(",", Arrays.stream(roles.split(",")).map(String::trim).toList());
435	        if (!value.isEmpty()) rolesOf(value);
436	        sheets.load(sheetId);
437	        String key = permissionKey(action);
438	        SheetSetting setting = settings.findBySheetIdAndKey(sheetId, key).orElse(null);
439	        try {
440	            if (value.isEmpty()) {
441	                if (setting != null) {
442	                    settings.delete(setting);
443	                    settings.flush();
444	                }
445	            } else if (setting == null) {
446	                settings.saveAndFlush(new SheetSetting(sheetId, key, value));
447	            } else {
448	                setting.setValue(value);
449	                settings.saveAndFlush(setting);
450	            }
451	        } catch (DataIntegrityViolationException raced) {
452	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The setting was changed by someone else.");
453	        }
454	        audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + user + " key=" + key + " value=" + value);
455	        return value;
456	    }
