485	    private Optional<Delegation> delegationOn(String sheetId, String user) {
486	        List<Delegation> made = delegations.findBySheetIdAndUserNameOrderByIdDesc(sheetId, user);
487	        if (made.isEmpty()) return Optional.empty();
488	        LocalDate today = sheets.today(sheetId);
