498	    /** Delegate the steward role to a user name from a date to a date, inclusive (blank from: the
499	     *  sheet's today); refused to anyone the sheet did not assign the steward role, and when the
500	     *  to-date is before the from-date. */
501	    @Transactional
502	    public Delegation delegate(String sheetId, String user, String userName, LocalDate from, LocalDate to) {
503	        sheets.load(sheetId);
504	        if (assignedRoleOf(sheetId, user) != Role.STEWARD) {
505	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can delegate the steward role.");
506	        }
507	        LocalDate start = from != null ? from : sheets.today(sheetId);
508	        LocalDate end = to != null ? to : start;
509	        if (end.isBefore(start)) {
510	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "The to-date is before the from-date.");
511	        }
512	        Delegation saved = delegations.saveAndFlush(new Delegation(sheetId, userName, start, end, user));
513	        audit.recordOnCommit("DELEGATED sheet=" + sheetId + " by=" + user + " user=" + userName + " from=" + start
514	                + " to=" + end);
515	        return saved;
516	    }
