518	    /** Assign a user name a role on the sheet, replacing the one it had. */
519	    @Transactional
520	    public SheetRole setRole(String sheetId, String user, String userName, Role role) {
521	        sheets.load(sheetId);
522	        SheetRole assigned = roles.findBySheetIdAndUserName(sheetId, userName).orElse(null);
523	        if (assigned == null) {
524	            assigned = new SheetRole(sheetId, userName, role);
525	        } else {
526	            assigned.setRole(role);
527	        }
528	        SheetRole saved;
529	        try {
530	            saved = roles.saveAndFlush(assigned);
531	        } catch (DataIntegrityViolationException raced) {
