271	    /** The settings in force on the sheet's today, with every dated value recorded. */
272	    private SettingsView view(String sheetId) {
273	        LocalDate today = service.today(sheetId);
274	        DatedSettings dated = service.dated(sheetId);
275	        Map<String, Integer> gradeTerms = new LinkedHashMap<>();
276	        for (Grade grade : Grade.values()) {
277	            Integer own = dated.gradeTermsOn(grade, today);
278	            if (own != null) gradeTerms.put(grade.name(), own);
279	        }
280	        Map<String, List<DatedView>> history = new LinkedHashMap<>();
281	        for (String key : dated.keys()) {
282	            history.put(key, dated.history(key).stream().map((s) -> new DatedView(s.getFrom(), s.getValue())).toList());
283	        }
284	        return new SettingsView(text(dated.clerkLimitOn(today)), dated.floorOn(today).toPlainString(),
285	                dated.termsOn(today), dated.latePctOn(today).toPlainString(), service.policyDate(sheetId),
286	                service.roles(sheetId).stream().map(RoleView::of).toList(), service.periodNumberingFrom(sheetId),
287	                gradeTerms, text(dated.capOn(today)), history, text(dated.proofThresholdOn(today)),
288	                service.permissions(sheetId), service.graceDays(sheetId),
289	                service.delegations(sheetId).stream().map(DelegationView::of).toList(),
290	                text(dated.noteThresholdOn(today)));
291	    }
